package com.oms.supplychain.service.wms;
import org.springframework.stereotype.Service;
import javax.annotation.Resource;
import com.ruoyi.common.core.domain.R;
import java.util.*;
import static com.oms.supplychain.service.wms.WmsStore.*;
/** Warehouse process orchestration. Remote calls never run inside local business transactions. */
@Service public class WmsProcessService {
 @Resource WmsStore db; @Resource WmsConnections connections; @Resource WmsInteractionLog logs;
 @Resource QimenProcessProtocol protocol; @Resource QimenProtocol qimen; @Resource ProcessStockClient stock;
 @SuppressWarnings("unchecked") private Map<String,Object> object(Object v){try{return v instanceof Map?(Map<String,Object>)v:db.json.readValue(v.toString(),Map.class);}catch(Exception e){throw new IllegalArgumentException("加工快照无法读取");}}
 private <T>T data(R<T> r){require(r!=null&&r.getCode()==200&&r.getData()!=null,r==null?"库存服务暂不可用":text(r.getMsg()));return r.getData();}
 private Map<String,Object> task(String c,long id){return db.one("SELECT * FROM wms_process_order WHERE company_code=? AND id=?",c,id);}
 private String hash(Object v){return QimenProtocol.hash("SHA-256",db.encode(v));}
 public Map<String,Object> options(String c,String keyword){require(keyword.length()<=128,"查询条件过长");return map("kits",db.jdbc.queryForList("SELECT b.sku_sn,g.goods_name,b.revision,b.components FROM goods_bundle b JOIN goods_sku_sn_info g ON UPPER(g.company_code)=b.company_code AND g.sku_sn=b.sku_sn WHERE b.company_code=? AND b.inventory_mode='STOCKED' AND b.enabled=1 AND (?='' OR b.sku_sn=? OR g.goods_name LIKE CONCAT('%',?,'%')) ORDER BY b.sku_sn LIMIT 100",c,keyword,keyword,keyword),"stores",db.jdbc.queryForList("SELECT v.wms_simulation_code store_code,v.wms_simulation_name store_name,w.real_store_code,o.owner_code,c.name connection_name,c.storeprocess_enabled FROM wms_simulation_store_info v JOIN owner_warehouse r ON r.id=v.owner_warehouse_id AND UPPER(r.company_code)=UPPER(v.company_code) JOIN owner_info o ON o.id=r.owner_id AND UPPER(o.company_code)=UPPER(r.company_code) JOIN wms_real_store_info w ON w.id=r.real_store_id AND UPPER(w.company_code)=UPPER(r.company_code) LEFT JOIN wms_connection c ON c.id=v.connection_id AND c.company_code=UPPER(v.company_code) WHERE UPPER(v.company_code)=? AND v.status=2 AND o.is_enable=2 AND r.status=2 AND w.status=2 ORDER BY v.id",c));}
 public List<Map<String,Object>> batches(String c,String sku,String store){return data(stock.batches(c,sku,store));}
 public Map<String,Object> list(String c,String keyword,String state,int page){require(keyword.length()<=128&&page>0&&page<=10000,"查询条件无效");String where=" WHERE company_code=?";List<Object> args=new ArrayList<>(Arrays.asList(c));if(!keyword.isEmpty()){where+=" AND (process_sn=? OR sku_sn=? OR external_order=?)";args.addAll(Arrays.asList(keyword,keyword,keyword));}if(!state.isEmpty()){require(Arrays.asList("DRAFT","RESERVING","READY","PARTIAL","COMPLETED","STOPPED").contains(state),"加工状态无效");where+=" AND state=?";args.add(state);}long total=db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_process_order"+where,Long.class,args.toArray());args.add((page-1)*20);return map("rows",db.jdbc.queryForList("SELECT id,process_sn,operation,sku_sn,goods_name,quantity,completed_quantity,store_code,state,dispatch_state,last_error,external_order,control_version,create_time FROM wms_process_order"+where+" ORDER BY id DESC LIMIT 20 OFFSET ?",args.toArray()),"total",total);}
 public Map<String,Object> detail(String c,long key){Map<String,Object> t=task(c,key);t.remove("lease_token");t.remove("lease_until");t.remove("payload_xml");t.put("recipe",object(t.remove("recipe_json")));if(t.get("stock_json")!=null)t.put("stock",object(t.remove("stock_json")));t.put("events",db.jdbc.queryForList("SELECT id,message_id,quantity,state,last_error,payload_json,reviewed,review_actor,review_reason,create_time FROM wms_process_event WHERE company_code=? AND process_id=? ORDER BY id DESC LIMIT 100",c,key));Map<String,Object> cfg=connections.get(c,id(t.get("connection_id")));t.put("can_cancel_warehouse",id(cfg.get("storeprocess_cancel"))==1);t.put("tickets",db.jdbc.queryForList("SELECT id,sn,business_type,inventory_status FROM wms_tickets WHERE UPPER(company_code)=? AND relation_sn=? AND business_type IN ('ASSEMBLY_OUT','ASSEMBLY_IN','DISASSEMBLY_OUT','DISASSEMBLY_IN') ORDER BY id",c,t.get("process_sn")));return t;}
 public long create(String c,Map<String,Object> input,String actor){String op=required(input,"operation",16),sku=required(input,"sku_sn",128),store=required(input,"store_code",64),request=required(input,"request_key",64),reason=required(input,"reason",255);long qty=id(input.get("quantity"));require(Arrays.asList("ASSEMBLE","DISASSEMBLE").contains(op)&&qty>0&&qty<=100000000,"请选择加工类型并填写有效套数");String requestHash=hash(new TreeMap<>(input));
  Map<String,Object> origin="DISASSEMBLE".equals(op)?data(stock.origin(c,id(input.get("source_batch_id")))):null;
  return db.tx().execute(tx->{db.jdbc.update("INSERT IGNORE INTO goods_master_lock(company_code) VALUES (?)",c);db.one("SELECT * FROM goods_master_lock WHERE company_code=? FOR UPDATE",c);List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_process_order WHERE company_code=? AND request_key=?",c,request);if(!old.isEmpty()){require(requestHash.equals(text(old.get(0).get("request_hash"))),"重复加工请求内容不一致");return id(old.get(0).get("id"));}
   Map<String,Object> kit=db.one("SELECT b.*,g.goods_name,g.is_package FROM goods_bundle b JOIN goods_sku_sn_info g ON UPPER(g.company_code)=b.company_code AND g.sku_sn=b.sku_sn WHERE b.company_code=? AND b.sku_sn=?",c,sku);require(id(kit.get("is_package"))==1&&"STOCKED".equals(kit.get("inventory_mode")),"请选择已发布的实物套装");require(id(kit.get("enabled"))==1||origin!=null,"套装组成已停用，不能新建组装单");Map<String,Object> recipe=map("sku_sn",sku,"goods_name",kit.get("goods_name"),"inventory_mode","STOCKED","revision",kit.get("revision"),"components",parseLines(kit.get("components")));if(origin!=null){require(sku.equals(origin.get("sku_sn"))&&store.equals(origin.get("store_code")),"拆卸批次与套装或仓库不一致");recipe=object(origin.get("recipe"));}
   Map<String,Object> v=resolve(c,store);return db.insert("wms_process_order",map("company_code",c,"process_sn","JG"+UUID.randomUUID().toString().replace("-",""),"request_key",request,"request_hash",requestHash,"operation",op,"sku_sn",sku,"goods_name",kit.get("goods_name"),"revision",recipe.get("revision"),"recipe_json",db.encode(recipe),"quantity",qty,"store_code",store,"real_store_code",v.get("real_store_code"),"owner_code",v.get("owner_code"),"connection_id",v.get("connection_id"),"external_warehouse",v.get("external_warehouse"),"external_owner",v.get("external_owner"),"source_batch_id",origin==null?null:input.get("source_batch_id"),"reason",reason,"created_by",actor));
  });
 }
 @SuppressWarnings("unchecked") private List<Map<String,Object>> parseLines(Object v){try{return v instanceof List?(List<Map<String,Object>>)v:db.json.readValue(v.toString(),List.class);}catch(Exception e){throw new IllegalArgumentException("套装组件快照无效");}}
 private Map<String,Object> resolve(String c,String store){Map<String,Object> v=db.one("SELECT v.*,r.status relation_status,o.owner_code,o.is_enable,w.real_store_code,w.status warehouse_status FROM wms_simulation_store_info v JOIN owner_warehouse r ON r.id=v.owner_warehouse_id AND UPPER(r.company_code)=UPPER(v.company_code) JOIN owner_info o ON o.id=r.owner_id AND UPPER(o.company_code)=UPPER(r.company_code) JOIN wms_real_store_info w ON w.id=r.real_store_id AND UPPER(w.company_code)=UPPER(r.company_code) WHERE UPPER(v.company_code)=? AND v.wms_simulation_code=?",c,store);require(id(v.get("status"))==2&&id(v.get("relation_status"))==2&&id(v.get("is_enable"))==2&&id(v.get("warehouse_status"))==2,"加工虚拟仓、实体仓或货主已停用");require(v.get("connection_id")!=null&&!text(v.get("external_warehouse")).isEmpty()&&!text(v.get("external_owner")).isEmpty(),"加工仓库连接或外部编码未配置");Map<String,Object> cfg=connections.usable(c,id(v.get("connection_id")));require("QIMEN".equals(cfg.get("provider"))&&"2.0".equals(cfg.get("api_version"))&&id(cfg.get("storeprocess_enabled"))==1,"该仓库尚未开通奇门仓内加工能力");return v;}
 private Map<String,Object> stockCommand(Map<String,Object> t){return map("process_sn",t.get("process_sn"),"operation",t.get("operation"),"store_code",t.get("store_code"),"quantity",t.get("quantity"),"source_batch_id",t.get("source_batch_id"),"recipe",object(t.get("recipe_json")));}
 public Map<String,Object> reserve(String c,long key,long version){Map<String,Object> t=db.tx().execute(tx->{Map<String,Object> locked=db.one("SELECT * FROM wms_process_order WHERE company_code=? AND id=? FOR UPDATE",c,key);require(id(locked.get("control_version"))==version,"加工单已变化，请刷新");require(Arrays.asList("DRAFT","RESERVING").contains(locked.get("state")),"当前状态不能审核占用");resolve(c,text(locked.get("store_code")));db.jdbc.update("UPDATE wms_process_order SET state='RESERVING',control_version=control_version+1 WHERE company_code=? AND id=?",c,key);return locked;});Map<String,Object> result=data(stock.execute(c,"reserve",stockCommand(t)));t.put("wire_time",t.get("create_time").toString().replace('T',' ').substring(0,19));String xml=protocol.create(t,object(t.get("recipe_json")),result);db.jdbc.update("UPDATE wms_process_order SET state='READY',stock_json=?,payload_xml=?,last_error='' WHERE company_code=? AND id=? AND state='RESERVING'",db.encode(result),xml,c,key);return detail(c,key);}
 public Map<String,Object> dispatch(String c,long key,long version){Map<String,Object> t=task(c,key);require(id(t.get("control_version"))==version,"加工单已变化，请刷新");require(Arrays.asList("READY","PARTIAL").contains(t.get("state")),"请先审核并占用加工投入");require(!"ACCEPTED".equals(t.get("dispatch_state")),"仓库已接收，请等待加工回传");require(!"CANCEL".equals(t.get("last_action")),"停止结果待核实，不能重新下发加工");String token=UUID.randomUUID().toString();int claimed=db.jdbc.update("UPDATE wms_process_order SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND),dispatch_state='SENDING',control_version=control_version+1 WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW()) AND dispatch_state<>'ACCEPTED' AND control_version=?",token,c,key,version);require(claimed==1,"加工交互正在执行，请刷新后核对");send(c,t,false,token);return detail(c,key);}
 private void send(String c,Map<String,Object> t,boolean cancel,String token){long key=id(t.get("id")),start=System.currentTimeMillis(),log=0;boolean contacted=false;try{db.jdbc.update("UPDATE wms_process_order SET last_action=? WHERE company_code=? AND id=? AND lease_token=?",cancel?"CANCEL":"CREATE",c,key,token);Map<String,Object> cfg=connections.get(c,id(t.get("connection_id")));if(!cancel){Map<String,Object> v=resolve(c,text(t.get("store_code")));for(String f:Arrays.asList("connection_id","external_warehouse","external_owner"))require(text(v.get(f)).equals(text(t.get(f))),"加工仓库映射已变化，请恢复原配置后重试");}String body=cancel?"<request>"+QimenProtocol.tag("orderCode",t.get("process_sn"))+QimenProtocol.tag("orderId",t.get("external_order"))+QimenProtocol.tag("ownerCode",t.get("external_owner"))+QimenProtocol.tag("warehouseCode",t.get("external_warehouse"))+QimenProtocol.tag("orderType","CNJG")+QimenProtocol.tag("cancelReason",t.get("reason"))+"</request>":text(t.get("payload_xml"));require(!body.isEmpty(),"加工下发快照缺失");WmsProtocol.Wire wire=protocol.wire(cfg,connections.secret(cfg),cancel?"taobao.qimen.order.cancel":"taobao.qimen.storeprocess.create",body);log=logs.start(c,id(cfg.get("id")),key,text(t.get("process_sn")),"OUT",cancel?"PROCESS_CANCEL":"PROCESS_CREATE",body);contacted=true;String response=WmsHttp.post(wire);WmsProtocol.Reply r=protocol.reply(response);if(r.success&&!cancel)require(!r.externalOrder.isEmpty(),"仓库未返回加工单号，请使用原单重试核对");if(r.success&&!cancel)require(text(t.get("external_order")).isEmpty()||text(t.get("external_order")).equals(r.externalOrder),"仓库加工单号变化，需核对");db.jdbc.update("UPDATE wms_process_order SET dispatch_state=?,external_order=IF(?='',external_order,?),last_error=?,lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",r.success?(cancel?"CANCELED":"ACCEPTED"):(cancel?"ACCEPTED":"FAILED"),r.externalOrder,r.externalOrder,r.success?"":r.message,c,key,token);logs.finish(log,r.success?"SUCCESS":"FAILED",response,r.success?"":r.message,System.currentTimeMillis()-start);logs.describe(log,r.success?(cancel?"仓库确认停止剩余加工，已完成结果保留":"仓库已受理加工任务，尚未转换实存"):"仓库拒绝本次加工操作");if(r.success&&cancel)release(c,key);
  }catch(Exception e){db.jdbc.update("UPDATE wms_process_order SET dispatch_state=?,last_error=?,lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?",contacted?"UNKNOWN":"FAILED",text(e.getMessage()).substring(0,Math.min(1000,text(e.getMessage()).length())),c,key,token);if(log>0)logs.finish(log,contacted?"UNKNOWN":"FAILED","",e.getMessage(),System.currentTimeMillis()-start);throw new IllegalArgumentException("加工交互未完成："+e.getMessage());}}
 public Map<String,Object> stop(String c,long key,long version,String reason){require(!reason.trim().isEmpty()&&reason.length()<=255,"请填写停止原因");Map<String,Object> t=db.tx().execute(tx->{Map<String,Object> r=db.one("SELECT * FROM wms_process_order WHERE company_code=? AND id=? FOR UPDATE",c,key);require(id(r.get("control_version"))==version,"加工单已变化，请刷新");require(!Arrays.asList("COMPLETED","STOPPED","RESERVING").contains(r.get("state")),"加工已结束或投入占用处理中");require(r.get("lease_until")==null||!((java.sql.Timestamp)r.get("lease_until")).toLocalDateTime().isAfter(java.time.LocalDateTime.now()),"加工交互正在执行");require(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_process_event WHERE company_code=? AND process_id=? AND state<>'POSTED'",Long.class,c,key)==0,"存在待核对或待记账回传，先处理后再停止");if(!"PENDING".equals(r.get("dispatch_state"))){Map<String,Object> cfg=connections.get(c,id(r.get("connection_id")));require(id(cfg.get("storeprocess_cancel"))==1,"该仓库未开通加工停止能力，请联系仓库核实，库存占用保留");require(Arrays.asList("ACCEPTED","CANCELED").contains(r.get("dispatch_state"))||"UNKNOWN".equals(r.get("dispatch_state"))&&"CANCEL".equals(r.get("last_action")),"受理或取消结果未知，请先核对仓库原单");}String token=UUID.randomUUID().toString();db.jdbc.update("UPDATE wms_process_order SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND),control_version=control_version+1,reason=? WHERE company_code=? AND id=?",token,reason,c,key);r.put("lease_token",token);r.put("reason",reason);return r;});if("PENDING".equals(t.get("dispatch_state"))||"CANCELED".equals(t.get("dispatch_state")))release(c,key);else send(c,t,true,text(t.get("lease_token")));return detail(c,key);}
 private void release(String c,long key){Map<String,Object> t=task(c,key);Map<String,Object> result="DRAFT".equals(t.get("state"))?Collections.emptyMap():data(stock.execute(c,"release",map("process_sn",t.get("process_sn"))));db.jdbc.update("UPDATE wms_process_order SET state='STOPPED',dispatch_state='CANCELED',stock_json=?,lease_token=NULL,lease_until=NULL,last_error='' WHERE company_code=? AND id=?",db.encode(result),c,key);}
 public String callback(String c,String callbackKey,Map<String,String> params,String body){Map<String,Object> cfg=db.one("SELECT * FROM wms_connection WHERE company_code=? AND callback_key=?",c,callbackKey);long start=System.currentTimeMillis(),log=logs.start(c,id(cfg.get("id")),null,"","IN","PROCESS_RECEIPT",body);try{Map<String,Object> payload=protocol.callback(cfg,connections.secret(cfg),params,body);String sn=text(payload.get("process_sn"));Map<String,Object> t=db.one("SELECT * FROM wms_process_order WHERE company_code=? AND process_sn=? AND connection_id=?",c,sn,cfg.get("id"));require(text(t.get("external_warehouse")).equals(payload.get("warehouse"))&&text(t.get("external_owner")).equals(payload.get("owner")),"加工回传仓库或货主不匹配");require(!text(payload.get("external_order")).isEmpty()&&(text(t.get("external_order")).isEmpty()||text(t.get("external_order")).equals(payload.get("external_order"))),"加工回传仓库单号不匹配");for(String group:Arrays.asList("materials","products"))for(Map<String,Object> line:parseLines(payload.get(group)))require(text(line.get("owner")).isEmpty()||text(t.get("external_owner")).equals(line.get("owner")),"加工明细货主不匹配");boolean assemble="ASSEMBLE".equals(t.get("operation"));payload.put("inputs",payload.remove(assemble?"materials":"products"));payload.put("outputs",payload.remove(assemble?"products":"materials"));db.jdbc.update("UPDATE wms_interaction_log SET task_id=?,ticket_sn=? WHERE id=?",t.get("id"),sn,log);final long sourceLog=log;String digest=hash(payload);long event=db.tx().execute(tx->{Map<String,Object> locked=db.one("SELECT * FROM wms_process_order WHERE company_code=? AND id=? FOR UPDATE",c,t.get("id"));require(!"DRAFT".equals(locked.get("state")),"尚未审核的加工单不能接收执行回传");List<Map<String,Object>> old=db.jdbc.queryForList("SELECT * FROM wms_process_event WHERE company_code=? AND process_id=? AND message_id=?",c,t.get("id"),payload.get("message_id"));if(!old.isEmpty()){require(digest.equals(old.get(0).get("payload_hash")),"同一加工回传消息内容冲突，原结果保留");return id(old.get(0).get("id"));}db.jdbc.update("UPDATE wms_process_order SET external_order=?,dispatch_state=IF(dispatch_state='CANCELED',dispatch_state,'ACCEPTED'),control_version=control_version+1 WHERE company_code=? AND id=?",payload.get("external_order"),c,t.get("id"));return db.insert("wms_process_event",map("company_code",c,"process_id",t.get("id"),"message_id",payload.get("message_id"),"payload_hash",digest,"payload_json",db.encode(payload),"quantity",payload.get("quantity"),"source_log_id",sourceLog));});post(c,id(t.get("id")),event,false);Map<String,Object> e=db.one("SELECT * FROM wms_process_event WHERE company_code=? AND id=?",c,event);logs.finish(log,"SUCCESS","", "",System.currentTimeMillis()-start);logs.describe(log,"POSTED".equals(e.get("state"))?"加工结果已成组记账，投入与产出流水已生成":"加工回传已保留，待核对或重试记账；本消息尚未确认完成");return qimen.acknowledgement(true,"加工回传已接收，记账结果请查看加工单");}catch(Exception e){logs.finish(log,"FAILED","",e.getMessage(),System.currentTimeMillis()-start);return qimen.acknowledgement(false,e.getMessage());}}
 public Map<String,Object> retryEvent(String c,long key,long event,boolean reviewed,String reason,String actor){if(reviewed)require(reason.trim().length()>=2&&reason.length()<=255,"人工确认差异须填写依据");if(reviewed){Map<String,Object> pending=db.one("SELECT * FROM wms_process_event WHERE company_code=? AND process_id=? AND id=?",c,key,event);require("WAIT_REVIEW".equals(pending.get("state")),"仅待核对回传允许确认差异");Map<String,Object> t=task(c,key);long log=logs.start(c,id(t.get("connection_id")),key,text(t.get("process_sn")),"LOCAL","PROCESS_REVIEW",db.encode(map("event_id",event,"actor",actor,"reason",reason)));db.jdbc.update("UPDATE wms_process_event SET reviewed=1,review_actor=?,review_reason=? WHERE company_code=? AND id=? AND state='WAIT_REVIEW'",actor,reason,c,event);logs.finish(log,"SUCCESS","","",0);logs.describe(log,"人工确认仓库实际加工差异，随后按原回传重试记账");}post(c,key,event,reviewed);return detail(c,key);}
 private void post(String c,long key,long event,boolean reviewed){Map<String,Object> e=db.one("SELECT * FROM wms_process_event WHERE company_code=? AND process_id=? AND id=?",c,key,event);if("POSTED".equals(e.get("state")))return;String token=UUID.randomUUID().toString();require(db.jdbc.update("UPDATE wms_process_order SET lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 90 SECOND) WHERE company_code=? AND id=? AND (lease_until IS NULL OR lease_until<NOW())",token,c,key)==1,"加工回传正在处理，可稍后重试");Map<String,Object> t=task(c,key);Map<String,Object> cmd=object(e.get("payload_json"));cmd.put("reviewed",id(e.get("reviewed"))==1);try{Map<String,Object> result=data(stock.execute(c,"post",cmd));db.tx().execute(tx->{Map<String,Object> locked=db.one("SELECT * FROM wms_process_order WHERE company_code=? AND id=? FOR UPDATE",c,key);require(token.equals(locked.get("lease_token")),"加工记账租约失效，可原消息重试");db.jdbc.update("UPDATE wms_process_event SET state='POSTED',last_error='' WHERE company_code=? AND id=?",c,event);db.jdbc.update("UPDATE wms_process_order SET completed_quantity=?,state=?,stock_json=?,last_error='',lease_token=NULL,lease_until=NULL,control_version=control_version+1 WHERE company_code=? AND id=?",result.get("completed_quantity"),result.get("state"),db.encode(result),c,key);tickets(c,t,event,cmd,result);return null;});}catch(Exception ex){db.jdbc.update("UPDATE wms_process_event SET state='WAIT_REVIEW',last_error=? WHERE company_code=? AND id=?",text(ex.getMessage()).substring(0,Math.min(1000,text(ex.getMessage()).length())),c,event);db.jdbc.update("UPDATE wms_process_order SET last_error=?,lease_token=NULL,lease_until=NULL WHERE company_code=? AND id=? AND lease_token=?","加工回传待核对："+text(ex.getMessage()).substring(0,Math.min(900,text(ex.getMessage()).length())),c,key,token);}}
 private void tickets(String c,Map<String,Object> t,long event,Map<String,Object> cmd,Map<String,Object> result){Map<String,Object> valued=cmd;if(result.get("events") instanceof List)for(Map<String,Object> posted:parseLines(result.get("events")))if(text(cmd.get("message_id")).equals(text(posted.get("message_id"))))valued=object(posted.get("result_json"));for(String side:Arrays.asList("OUT","IN")){String sn=text(t.get("process_sn"))+"_"+event+"_"+side;if(db.jdbc.queryForObject("SELECT COUNT(*) FROM wms_tickets WHERE UPPER(company_code)=? AND sn=?",Long.class,c,sn)>0)continue;String type=("ASSEMBLE".equals(t.get("operation"))?"ASSEMBLY_":"DISASSEMBLY_")+side;db.insert("wms_tickets",map("company_code",c,"sn",sn,"ticket_type","IN".equals(side)?1:2,"business_type",type,"relation_sn",t.get("process_sn"),"original_sn",t.get("process_sn"),"wms_simulation_code",t.get("store_code"),"real_store_code",t.get("real_store_code"),"status_ticket",2,"status_notify",1,"inventory_status",2,"user_name","WMS","remark","套装加工记账凭证，已通过加工单通知仓库，不重复下发"));for(Map<String,Object> line:parseLines(valued.get("OUT".equals(side)?"inputs":"outputs"))){long qty=id(line.get("quantity"));boolean good="ZP".equals(line.get("inventory_type"));db.insert("wms_tickets_goods",map("company_code",c,"sn",sn,"inventory_type",good?"ZP":"CP","sku_sn",line.get("sku_sn"),"batch_code",line.get("batch_code"),"purchase_price",line.getOrDefault("unit_cost",0),"number_expected",qty,"number_actually",qty,"number_zp",good?qty:0,"number_cp",good?0:qty,"inventory_is_handle",2));}}}
}
